const https = require('https');

async function script(input) {
    const alertData = JSON.stringify({
        event: input.event,
        severity: input.severity,
        details: input.details,
        timestamp: new Date().toISOString()
    });

    const options = {
        hostname: 'qstash-eu-central-1.upstash.io',
        port: 443,
        path: '/v2/publish/https://webhook.site/your-id-here', 
        method: 'POST',
        headers: {
            'Authorization': 'Bearer eyJVc2VySUQiOiIzNjVhNzUyMi04NmExLTQ0MDktYmZlMC01ZjgzNDI3M2RlNDciLCJQYXNzd29yZCI6ImQzMDA4NjUyZTgzMDRmYzBhNDYwNGJmMGY5NGEzNGUwIn0=',
            'Content-Type': 'application/json',
            'Content-Length': Buffer.byteLength(alertData)
        }
    };

    return new Promise((resolve) => {
        const req = https.request(options, (res) => {
            let body = '';
            res.on('data', c => body += c);
            res.on('end', () => resolve({ status: "Success", details: body }));
        });
        req.on('error', e => resolve({ status: "Error", msg: e.message }));
        req.write(alertData);
        req.end();
    });
}
